<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LumiFlowOn — Profile Wallet Address</title>@include('partials.lumiflowon-financial-theme')</head><body>@include('partials.lumiflowon-financial-nav')<main style="max-width:800px;margin:20px auto;padding:20px"><h1>Update Profile Wallet Address</h1><form id="profile-wallet-form">@csrf<label>Network<select name="network"><option>BEP20</option><option>TRC20</option></select></label><label>Your receiving address<input name="address" maxlength="64" required placeholder="0x… or T…"></label><button type="button" id="send-wallet-otp">Send Email OTP</button><input name="otp_challenge_id" type="hidden"><label>Email OTP<input name="email_otp" pattern="[0-9]{6}" maxlength="6" inputmode="numeric" autocomplete="one-time-code" required></label><button type="submit">Verify OTP & Save Address</button></form><p id="wallet-status" role="status" aria-live="polite"></p><h2>Current profile wallets</h2><div id="wallets"></div><a href="{{ route('member.profile') }}">Back to Profile</a></main><script>
(()=>{const form=document.getElementById('profile-wallet-form'),status=document.getElementById('wallet-status');const call=async(url,data)=>{const r=await fetch(url,{method:data?'POST':'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':form.querySelector('[name=_token]').value},body:data?JSON.stringify(data):undefined});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message||'Unable to save address.');return d;};const data=()=>({network:form.network.value,address:form.address.value.trim()});const refresh=async()=>{const d=await call('/member/usdt-wallets');const list=document.getElementById('wallets');list.replaceChildren();for(const w of d.wallets){const p=document.createElement('p');p.style.overflowWrap='anywhere';p.textContent=w.network+': '+w.address;list.append(p);}};const show=(message,ok)=>{status.textContent=message;status.style.color=ok?'#86efac':'#fda4af';};document.getElementById('send-wallet-otp').onclick=async e=>{e.target.disabled=true;try{const d=await call({{ Illuminate\Support\Js::from(route('member.wallet-otp.send')) }},data());form.otp_challenge_id.value=d.challenge_id;show(d.message,true);}catch(e){show(e.message,false);}finally{e.target.disabled=false;}};form.onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const d=await call({{ Illuminate\Support\Js::from(route('member.wallet-otp.save')) }},{...data(),otp_challenge_id:form.otp_challenge_id.value,email_otp:form.email_otp.value});form.email_otp.value='';form.otp_challenge_id.value='';show(d.message,true);await refresh();}catch(e){show(e.message,false);}finally{b.disabled=false;}};refresh().catch(e=>show(e.message,false));})();
</script></body></html>
